const express = require('express');
const Database = require('better-sqlite3');
const XLSX = require('xlsx');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const APP_DIR = '/app';
const DB_PATH = path.join(APP_DIR, 'dropline.db');
const PUBLIC_DIR = path.join(APP_DIR, 'public');
const SEED_PATH = '/assets/artifacts/dropline_seed.xlsx';
const PORT = 3000;

const app = express();
const db = new Database(DB_PATH);

db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

const schema = `
CREATE TABLE IF NOT EXISTS meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS accounts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  password_hash TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS tokens (
  token_hash TEXT PRIMARY KEY,
  account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS game_state (
  account_id INTEGER PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
  board_json TEXT NOT NULL,
  current_player TEXT NOT NULL,
  status TEXT NOT NULL,
  winner_color TEXT,
  winning_cells_json TEXT NOT NULL,
  red_wins INTEGER NOT NULL DEFAULT 0,
  yellow_wins INTEGER NOT NULL DEFAULT 0,
  draws INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS moves (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  move_number INTEGER NOT NULL,
  color TEXT NOT NULL,
  column_index INTEGER NOT NULL,
  row_index INTEGER NOT NULL,
  applied INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(account_id, move_number)
);

CREATE INDEX IF NOT EXISTS idx_tokens_account ON tokens(account_id);
CREATE INDEX IF NOT EXISTS idx_moves_account_applied ON moves(account_id, applied, move_number);
`;

function sha256(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function hashPassword(password, salt) {
  return crypto.pbkdf2Sync(password, salt, 120000, 32, 'sha256').toString('hex');
}

function newPasswordHash(password) {
  const salt = crypto.randomBytes(16).toString('hex');
  return { salt, hash: hashPassword(password, salt) };
}

function emptyBoard() {
  return Array.from({ length: 42 }, () => null);
}

function parseWinningCells(value) {
  if (!value || value === 'none') {
    return [];
  }
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function parseBoard(value) {
  if (!value) {
    return emptyBoard();
  }
  if (Array.isArray(value) && value.length === 42) {
    return value.map((cell) => (cell === 'Red' || cell === 'Yellow' ? cell : null));
  }
  const text = String(value).trim();
  if (/^42 empty cells$/i.test(text)) {
    return emptyBoard();
  }
  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed) && parsed.length === 42) {
      return parsed.map((cell) => (cell === 'Red' || cell === 'Yellow' ? cell : null));
    }
  } catch {
    // fall through
  }
  return emptyBoard();
}

function serializeBoard(board) {
  return JSON.stringify(board);
}

function serializeWinningCells(cells) {
  return JSON.stringify(cells || []);
}

function rowColToIndex(row, col) {
  return row * 7 + col;
}

function indexToRowCol(index) {
  return { row: Math.floor(index / 7), col: index % 7 };
}

function dropInColumn(board, columnIndex, color) {
  for (let row = 5; row >= 0; row -= 1) {
    const index = rowColToIndex(row, columnIndex);
    if (board[index] === null) {
      const nextBoard = board.slice();
      nextBoard[index] = color;
      return { rowIndex: row, board: nextBoard };
    }
  }
  return null;
}

function detectWinningCells(board, rowIndex, columnIndex, color) {
  const directions = [
    [0, 1],
    [1, 0],
    [1, 1],
    [1, -1],
  ];

  for (const [dr, dc] of directions) {
    const cells = [rowColToIndex(rowIndex, columnIndex)];

    let r = rowIndex - dr;
    let c = columnIndex - dc;
    while (r >= 0 && r < 6 && c >= 0 && c < 7 && board[rowColToIndex(r, c)] === color) {
      cells.unshift(rowColToIndex(r, c));
      r -= dr;
      c -= dc;
    }

    r = rowIndex + dr;
    c = columnIndex + dc;
    while (r >= 0 && r < 6 && c >= 0 && c < 7 && board[rowColToIndex(r, c)] === color) {
      cells.push(rowColToIndex(r, c));
      r += dr;
      c += dc;
    }

    if (cells.length >= 4) {
      const anchor = cells.indexOf(rowColToIndex(rowIndex, columnIndex));
      let start = Math.max(0, anchor - 3);
      if (start + 4 > cells.length) {
        start = cells.length - 4;
      }
      return cells.slice(start, start + 4);
    }
  }

  return [];
}

function boardIsFull(board) {
  return board.every((cell) => cell !== null);
}

function makeInitialGameState(row) {
  return {
    board_json: serializeBoard(parseBoard(row.Board)),
    current_player: row['Current player'] || 'Red',
    status: row.Status || 'active',
    winner_color: null,
    winning_cells_json: serializeWinningCells(parseWinningCells(row['Winning cells'])),
    red_wins: Number(row['Red wins'] || 0),
    yellow_wins: Number(row['Yellow wins'] || 0),
    draws: Number(row.Draws || 0),
  };
}

function loadSeedRows() {
  const workbook = XLSX.readFile(SEED_PATH);
  const accountsSheet = workbook.Sheets.Accounts;
  const stateSheet = workbook.Sheets['Initial Game State'];
  const accounts = XLSX.utils.sheet_to_json(accountsSheet, { defval: '' });
  const states = XLSX.utils.sheet_to_json(stateSheet, { defval: '' });
  const stateByEmail = new Map(states.map((row) => [String(row['Account email']).trim(), row]));
  return accounts.map((account) => {
    const stateRow = stateByEmail.get(String(account.Email).trim());
    if (!stateRow) {
      throw new Error(`Missing seed state for ${account.Email}`);
    }
    return { account, stateRow };
  });
}

function ensureSchemaAndSeed() {
  db.exec(schema);
  const seeded = db.prepare('SELECT value FROM meta WHERE key = ?').get('seeded');
  if (seeded) {
    return;
  }

  if (!fs.existsSync(SEED_PATH)) {
    throw new Error(`Missing seed workbook at ${SEED_PATH}`);
  }

  const seedRows = loadSeedRows();
  const insertAccount = db.prepare('INSERT INTO accounts (email, name, password_salt, password_hash) VALUES (?, ?, ?, ?)');
  const insertGame = db.prepare(`
    INSERT INTO game_state (
      account_id, board_json, current_player, status, winner_color, winning_cells_json,
      red_wins, yellow_wins, draws
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);
  const insertMeta = db.prepare('INSERT INTO meta (key, value) VALUES (?, ?)');

  const seed = db.transaction(() => {
    for (const { account, stateRow } of seedRows) {
      const passwordInfo = newPasswordHash(String(account.Password));
      const accountInfo = insertAccount.run(String(account.Email).trim(), String(account.Name).trim(), passwordInfo.salt, passwordInfo.hash);
      const state = makeInitialGameState(stateRow);
      insertGame.run(
        accountInfo.lastInsertRowid,
        state.board_json,
        state.current_player,
        state.status,
        state.winner_color,
        state.winning_cells_json,
        state.red_wins,
        state.yellow_wins,
        state.draws,
      );
    }
    insertMeta.run('seeded', '1');
  });

  seed();
}

ensureSchemaAndSeed();

app.use(express.json());
app.use(express.static(PUBLIC_DIR));

function getTokenFromRequest(req) {
  const header = req.headers.authorization || '';
  const match = header.match(/^Bearer\s+(.+)$/i);
  return match ? match[1].trim() : null;
}

function sendError(res, status, message) {
  res.status(status).json({ error: message });
}

function getAccountByToken(token) {
  if (!token) {
    return null;
  }
  const tokenHash = sha256(token);
  return db.prepare(`
    SELECT a.id, a.email, a.name
    FROM tokens t
    JOIN accounts a ON a.id = t.account_id
    WHERE t.token_hash = ?
  `).get(tokenHash) || null;
}

function requireAuth(req, res) {
  const token = getTokenFromRequest(req);
  const account = getAccountByToken(token);
  if (!account) {
    sendError(res, 401, 'Authentication required.');
    return null;
  }
  return { token, account };
}

function getGameRow(accountId) {
  return db.prepare('SELECT * FROM game_state WHERE account_id = ?').get(accountId);
}

function getMoves(accountId) {
  return db.prepare('SELECT move_number, color, column_index, row_index, applied FROM moves WHERE account_id = ? ORDER BY move_number ASC').all(accountId);
}

function mapStateRow(row) {
  return {
    board: JSON.parse(row.board_json),
    currentPlayer: row.current_player,
    status: row.status,
    winnerColor: row.winner_color,
    winningCells: JSON.parse(row.winning_cells_json),
    totals: {
      redWins: row.red_wins,
      yellowWins: row.yellow_wins,
      draws: row.draws,
    },
  };
}

function buildPayload(account, gameRow, moves, feedback = '') {
  const state = mapStateRow(gameRow);
  const appliedMoves = moves
    .filter((move) => move.applied === 1)
    .map((move) => ({
      moveNumber: move.move_number,
      color: move.color,
      column: move.column_index + 1,
      row: move.row_index + 1,
    }));
  const redoMoves = moves.filter((move) => move.applied === 0);
  const statusText = state.status === 'active'
    ? `${state.currentPlayer}'s turn`
    : state.status === 'won'
      ? `${state.winnerColor} wins`
      : 'Draw';

  return {
    account,
    board: state.board,
    currentPlayer: state.currentPlayer,
    status: state.status,
    statusText,
    winnerColor: state.winnerColor,
    winningCells: state.winningCells,
    totals: state.totals,
    history: appliedMoves,
    canUndo: appliedMoves.length > 0,
    canRedo: redoMoves.length > 0,
    feedback,
  };
}

function getSessionPayload(accountId, feedback = '') {
  const accountRow = db.prepare('SELECT id, email, name FROM accounts WHERE id = ?').get(accountId);
  const gameRow = getGameRow(accountId);
  const moves = getMoves(accountId);
  return buildPayload(
    { id: accountRow.id, email: accountRow.email, name: accountRow.name },
    gameRow,
    moves,
    feedback,
  );
}

function createToken(accountId) {
  const token = crypto.randomBytes(32).toString('base64url');
  db.prepare('INSERT INTO tokens (token_hash, account_id) VALUES (?, ?)').run(sha256(token), accountId);
  return token;
}

function getMoveCount(accountId) {
  const row = db.prepare('SELECT COALESCE(MAX(move_number), 0) AS max_move FROM moves WHERE account_id = ?').get(accountId);
  return row.max_move;
}

function setGameState(accountId, updater) {
  const current = getGameRow(accountId);
  const next = updater({
    board: JSON.parse(current.board_json),
    currentPlayer: current.current_player,
    status: current.status,
    winnerColor: current.winner_color,
    winningCells: JSON.parse(current.winning_cells_json),
    totals: {
      redWins: current.red_wins,
      yellowWins: current.yellow_wins,
      draws: current.draws,
    },
  });

  db.prepare(`
    UPDATE game_state
    SET board_json = ?, current_player = ?, status = ?, winner_color = ?, winning_cells_json = ?,
        red_wins = ?, yellow_wins = ?, draws = ?, updated_at = CURRENT_TIMESTAMP
    WHERE account_id = ?
  `).run(
    serializeBoard(next.board),
    next.currentPlayer,
    next.status,
    next.winnerColor,
    serializeWinningCells(next.winningCells),
    next.totals.redWins,
    next.totals.yellowWins,
    next.totals.draws,
    accountId,
  );
}

function resetToNewGame(accountId) {
  db.prepare('DELETE FROM moves WHERE account_id = ?').run(accountId);
  setGameState(accountId, (state) => ({
    ...state,
    board: emptyBoard(),
    currentPlayer: 'Red',
    status: 'active',
    winnerColor: null,
    winningCells: [],
  }));
}

function applyMove(accountId, columnOneBased) {
  const columnIndex = columnOneBased - 1;
  const current = getGameRow(accountId);
  const state = {
    board: JSON.parse(current.board_json),
    currentPlayer: current.current_player,
    status: current.status,
    winnerColor: current.winner_color,
    winningCells: JSON.parse(current.winning_cells_json),
    totals: {
      redWins: current.red_wins,
      yellowWins: current.yellow_wins,
      draws: current.draws,
    },
  };

  if (state.status !== 'active') {
    return { ok: false, status: 409, message: 'Game is over. Start a new game.' };
  }

  if (!Number.isInteger(columnOneBased) || columnOneBased < 1 || columnOneBased > 7) {
    return { ok: false, status: 400, message: 'Choose a column from 1 to 7.' };
  }

  const dropped = dropInColumn(state.board, columnIndex, state.currentPlayer);
  if (!dropped) {
    return { ok: false, status: 409, message: `Column ${columnOneBased} is full` };
  }

  const nextBoard = dropped.board;
  const winningCells = detectWinningCells(nextBoard, dropped.rowIndex, columnIndex, state.currentPlayer);
  const nextMoveNumber = getMoveCount(accountId) + 1;

  const insertMove = db.prepare(`
    INSERT INTO moves (account_id, move_number, color, column_index, row_index, applied)
    VALUES (?, ?, ?, ?, ?, 1)
  `);

  const run = db.transaction(() => {
    db.prepare('DELETE FROM moves WHERE account_id = ? AND applied = 0').run(accountId);
    insertMove.run(accountId, nextMoveNumber, state.currentPlayer, columnIndex, dropped.rowIndex);

    if (winningCells.length === 4) {
      const winnerKey = state.currentPlayer === 'Red' ? 'redWins' : 'yellowWins';
      state.totals[winnerKey] += 1;
      db.prepare(`
        UPDATE game_state
        SET board_json = ?, current_player = ?, status = 'won', winner_color = ?, winning_cells_json = ?,
            red_wins = ?, yellow_wins = ?, draws = ?, updated_at = CURRENT_TIMESTAMP
        WHERE account_id = ?
      `).run(
        serializeBoard(nextBoard),
        state.currentPlayer === 'Red' ? 'Yellow' : 'Red',
        state.currentPlayer,
        serializeWinningCells(winningCells),
        state.totals.redWins,
        state.totals.yellowWins,
        state.totals.draws,
        accountId,
      );
      return;
    }

    if (boardIsFull(nextBoard)) {
      state.totals.draws += 1;
      db.prepare(`
        UPDATE game_state
        SET board_json = ?, current_player = ?, status = 'draw', winner_color = NULL, winning_cells_json = ?,
            red_wins = ?, yellow_wins = ?, draws = ?, updated_at = CURRENT_TIMESTAMP
        WHERE account_id = ?
      `).run(
        serializeBoard(nextBoard),
        state.currentPlayer === 'Red' ? 'Yellow' : 'Red',
        serializeWinningCells([]),
        state.totals.redWins,
        state.totals.yellowWins,
        state.totals.draws,
        accountId,
      );
      return;
    }

    db.prepare(`
      UPDATE game_state
      SET board_json = ?, current_player = ?, status = 'active', winner_color = NULL, winning_cells_json = ?,
          red_wins = ?, yellow_wins = ?, draws = ?, updated_at = CURRENT_TIMESTAMP
      WHERE account_id = ?
    `).run(
      serializeBoard(nextBoard),
      state.currentPlayer === 'Red' ? 'Yellow' : 'Red',
      serializeWinningCells([]),
      state.totals.redWins,
      state.totals.yellowWins,
      state.totals.draws,
      accountId,
    );
  });

  run();
  return { ok: true, feedback: '' };
}

function undoMove(accountId) {
  const current = getGameRow(accountId);
  const lastMove = db.prepare(`
    SELECT * FROM moves
    WHERE account_id = ? AND applied = 1
    ORDER BY move_number DESC
    LIMIT 1
  `).get(accountId);

  if (!lastMove) {
    return { ok: false, status: 409, message: 'Nothing to undo' };
  }

  const state = {
    board: JSON.parse(current.board_json),
    currentPlayer: current.current_player,
    status: current.status,
    winnerColor: current.winner_color,
    winningCells: JSON.parse(current.winning_cells_json),
    totals: {
      redWins: current.red_wins,
      yellowWins: current.yellow_wins,
      draws: current.draws,
    },
  };

  const index = rowColToIndex(lastMove.row_index, lastMove.column_index);
  state.board[index] = null;
  state.currentPlayer = lastMove.color;
  state.status = 'active';
  state.winnerColor = null;
  state.winningCells = [];
  if (current.status === 'won') {
    if (current.winner_color === 'Red') {
      state.totals.redWins -= 1;
    } else if (current.winner_color === 'Yellow') {
      state.totals.yellowWins -= 1;
    }
  } else if (current.status === 'draw') {
    state.totals.draws -= 1;
  }

  const run = db.transaction(() => {
    db.prepare('UPDATE moves SET applied = 0 WHERE account_id = ? AND move_number = ?').run(accountId, lastMove.move_number);
    db.prepare(`
      UPDATE game_state
      SET board_json = ?, current_player = ?, status = 'active', winner_color = NULL, winning_cells_json = ?,
          red_wins = ?, yellow_wins = ?, draws = ?, updated_at = CURRENT_TIMESTAMP
      WHERE account_id = ?
    `).run(
      serializeBoard(state.board),
      state.currentPlayer,
      serializeWinningCells([]),
      state.totals.redWins,
      state.totals.yellowWins,
      state.totals.draws,
      accountId,
    );
  });

  run();
  return { ok: true, feedback: '' };
}

function redoMove(accountId) {
  const undoneMove = db.prepare(`
    SELECT * FROM moves
    WHERE account_id = ? AND applied = 0
    ORDER BY move_number DESC
    LIMIT 1
  `).get(accountId);

  if (!undoneMove) {
    return { ok: false, status: 409, message: 'Nothing to redo' };
  }

  const current = getGameRow(accountId);
  const state = {
    board: JSON.parse(current.board_json),
    currentPlayer: current.current_player,
    status: current.status,
    winnerColor: current.winner_color,
    winningCells: JSON.parse(current.winning_cells_json),
    totals: {
      redWins: current.red_wins,
      yellowWins: current.yellow_wins,
      draws: current.draws,
    },
  };

  if (state.status !== 'active') {
    return { ok: false, status: 409, message: 'Game is over. Start a new game.' };
  }

  const index = rowColToIndex(undoneMove.row_index, undoneMove.column_index);
  if (state.board[index] !== null) {
    return { ok: false, status: 409, message: 'That move can no longer be redone.' };
  }

  state.board[index] = undoneMove.color;
  const winningCells = detectWinningCells(state.board, undoneMove.row_index, undoneMove.column_index, undoneMove.color);

  const run = db.transaction(() => {
    db.prepare('UPDATE moves SET applied = 1 WHERE account_id = ? AND move_number = ?').run(accountId, undoneMove.move_number);

    if (winningCells.length === 4) {
      const winnerKey = undoneMove.color === 'Red' ? 'redWins' : 'yellowWins';
      state.totals[winnerKey] += 1;
      db.prepare(`
        UPDATE game_state
        SET board_json = ?, current_player = ?, status = 'won', winner_color = ?, winning_cells_json = ?,
            red_wins = ?, yellow_wins = ?, draws = ?, updated_at = CURRENT_TIMESTAMP
        WHERE account_id = ?
      `).run(
        serializeBoard(state.board),
        undoneMove.color === 'Red' ? 'Yellow' : 'Red',
        undoneMove.color,
        serializeWinningCells(winningCells),
        state.totals.redWins,
        state.totals.yellowWins,
        state.totals.draws,
        accountId,
      );
      return;
    }

    if (boardIsFull(state.board)) {
      state.totals.draws += 1;
      db.prepare(`
        UPDATE game_state
        SET board_json = ?, current_player = ?, status = 'draw', winner_color = NULL, winning_cells_json = ?,
            red_wins = ?, yellow_wins = ?, draws = ?, updated_at = CURRENT_TIMESTAMP
        WHERE account_id = ?
      `).run(
        serializeBoard(state.board),
        undoneMove.color === 'Red' ? 'Yellow' : 'Red',
        serializeWinningCells([]),
        state.totals.redWins,
        state.totals.yellowWins,
        state.totals.draws,
        accountId,
      );
      return;
    }

    db.prepare(`
      UPDATE game_state
      SET board_json = ?, current_player = ?, status = 'active', winner_color = NULL, winning_cells_json = ?,
          red_wins = ?, yellow_wins = ?, draws = ?, updated_at = CURRENT_TIMESTAMP
      WHERE account_id = ?
    `).run(
      serializeBoard(state.board),
      undoneMove.color === 'Red' ? 'Yellow' : 'Red',
      serializeWinningCells([]),
      state.totals.redWins,
      state.totals.yellowWins,
      state.totals.draws,
      accountId,
    );
  });

  run();
  return { ok: true, feedback: '' };
}

function clearRedoStack(accountId) {
  db.prepare('DELETE FROM moves WHERE account_id = ? AND applied = 0').run(accountId);
}

app.get('/api/health', (_req, res) => {
  res.json({ ok: true });
});

app.get('/health', (_req, res) => {
  res.json({ ok: true });
});

app.post('/api/login', (req, res) => {
  const email = String(req.body?.email || '').trim().toLowerCase();
  const password = String(req.body?.password || '');
  const account = db.prepare('SELECT * FROM accounts WHERE lower(email) = ?').get(email);
  if (!account) {
    return sendError(res, 401, 'Incorrect email or password.');
  }
  const computed = hashPassword(password, account.password_salt);
  if (computed !== account.password_hash) {
    return sendError(res, 401, 'Incorrect email or password.');
  }

  const token = createToken(account.id);
  const payload = getSessionPayload(account.id);
  res.json({ token, ...payload });
});

app.post('/api/logout', (req, res) => {
  const auth = requireAuth(req, res);
  if (!auth) {
    return;
  }
  db.prepare('DELETE FROM tokens WHERE token_hash = ?').run(sha256(auth.token));
  res.json({ ok: true });
});

app.get('/api/bootstrap', (req, res) => {
  const auth = requireAuth(req, res);
  if (!auth) {
    return;
  }
  res.json({ token: auth.token, ...getSessionPayload(auth.account.id) });
});

app.get('/api/state', (req, res) => {
  const auth = requireAuth(req, res);
  if (!auth) {
    return;
  }
  res.json(getSessionPayload(auth.account.id));
});

app.post('/api/move', (req, res) => {
  const auth = requireAuth(req, res);
  if (!auth) {
    return;
  }

  const column = Number(req.body?.column);
  const outcome = applyMove(auth.account.id, column);
  if (!outcome.ok) {
    return sendError(res, outcome.status, outcome.message);
  }

  res.json(getSessionPayload(auth.account.id));
});

app.post('/api/undo', (req, res) => {
  const auth = requireAuth(req, res);
  if (!auth) {
    return;
  }

  const outcome = undoMove(auth.account.id);
  if (!outcome.ok) {
    return sendError(res, outcome.status, outcome.message);
  }

  res.json(getSessionPayload(auth.account.id));
});

app.post('/api/redo', (req, res) => {
  const auth = requireAuth(req, res);
  if (!auth) {
    return;
  }

  const outcome = redoMove(auth.account.id);
  if (!outcome.ok) {
    return sendError(res, outcome.status, outcome.message);
  }

  res.json(getSessionPayload(auth.account.id));
});

app.post('/api/new-game', (req, res) => {
  const auth = requireAuth(req, res);
  if (!auth) {
    return;
  }

  db.transaction(() => {
    resetToNewGame(auth.account.id);
  })();

  res.json(getSessionPayload(auth.account.id, 'New game started'));
});

app.get('/', (_req, res) => {
  res.sendFile(path.join(PUBLIC_DIR, 'index.html'));
});

app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: 'Unexpected server error.' });
});

app.listen(PORT, '0.0.0.0', () => {
  console.log(`DropLine listening on 0.0.0.0:${PORT}`);
});

:root {
  color-scheme: dark;
  --bg: #0b1020;
  --panel: rgba(15, 23, 42, 0.88);
  --panel-border: rgba(148, 163, 184, 0.18);
  --text: #e5eefc;
  --muted: #9fb0cc;
  --accent: #6ee7ff;
  --red: #ff6b6b;
  --yellow: #ffd166;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.38);
  --radius: 24px;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
  background:
    radial-gradient(circle at top left, rgba(59, 130, 246, 0.22), transparent 30%),
    radial-gradient(circle at top right, rgba(168, 85, 247, 0.18), transparent 26%),
    linear-gradient(180deg, #0a0f1c 0%, #11182a 100%);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

body {
  padding: 16px;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

.hidden {
  display: none !important;
}

.app-shell {
  width: min(1120px, 100%);
  margin: 0 auto;
}

.topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.eyebrow {
  margin: 0 0 6px;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.75rem;
  font-weight: 700;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 8px;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1;
}

.lede,
.subtle,
.feedback,
.availability-text {
  color: var(--muted);
}

.lede {
  margin-bottom: 0;
  max-width: 60ch;
}

.account-badge {
  align-self: center;
  padding: 12px 16px;
  border: 1px solid var(--panel-border);
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.72);
  color: var(--text);
  box-shadow: var(--shadow);
}

.panel {
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
}

.auth-panel {
  width: min(520px, 100%);
  margin: 48px auto 0;
  padding: 28px;
}

.panel-copy p,
.panel-head p,
.availability-text,
.feedback {
  margin-bottom: 0;
}

.auth-form {
  display: grid;
  gap: 16px;
  margin-top: 24px;
}

.auth-form label {
  display: grid;
  gap: 8px;
  color: #d8e4f7;
  font-weight: 600;
}

.auth-form input {
  width: 100%;
  padding: 14px 16px;
  border-radius: 14px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(6, 10, 22, 0.72);
  color: var(--text);
}

.auth-form input:focus,
button:focus-visible {
  outline: 2px solid rgba(110, 231, 255, 0.9);
  outline-offset: 2px;
}

.primary-button,
.ghost-button {
  border-radius: 14px;
  border: 1px solid transparent;
  padding: 12px 16px;
  font-weight: 700;
  transition: transform 140ms ease, border-color 140ms ease, background 140ms ease, opacity 140ms ease;
}

.primary-button {
  background: linear-gradient(135deg, #58cfff, #7c5cff);
  color: #07111f;
}

.primary-button.secondary {
  background: linear-gradient(135deg, #fff0a8, #ffd166);
}

.ghost-button {
  background: rgba(15, 23, 42, 0.68);
  color: var(--text);
  border-color: rgba(148, 163, 184, 0.2);
}

button:hover:not(:disabled) {
  transform: translateY(-1px);
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
  transform: none;
}

.feedback {
  min-height: 1.25rem;
  margin-top: 14px;
}

.game-screen {
  margin-top: 8px;
}

.game-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.75fr) minmax(280px, 0.85fr);
  gap: 18px;
  align-items: start;
}

.board-panel,
.history-panel {
  padding: 22px;
}

.panel-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 18px;
}

.panel-head.stack {
  align-items: flex-start;
}

.status-text {
  margin-bottom: 4px;
  font-size: clamp(1.2rem, 2vw, 1.65rem);
}

.scoreboard {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.score-card {
  padding: 14px 16px;
  border-radius: 18px;
  background: rgba(6, 10, 22, 0.56);
  border: 1px solid rgba(148, 163, 184, 0.16);
}

.score-card span {
  display: block;
  color: var(--muted);
  font-size: 0.92rem;
}

.score-card strong {
  display: block;
  margin-top: 8px;
  font-size: 1.65rem;
}

.score-card.red strong {
  color: var(--red);
}

.score-card.yellow strong {
  color: var(--yellow);
}

.score-card.draw strong {
  color: var(--accent);
}

.column-controls {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 14px;
}

.column-controls button {
  min-height: 44px;
  padding: 10px 8px;
  border-radius: 14px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.78);
  color: var(--text);
}

.board-frame {
  padding: 14px;
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(29, 78, 216, 0.32), rgba(37, 99, 235, 0.08));
  border: 1px solid rgba(96, 165, 250, 0.16);
}

.board {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 10px;
}

.cell {
  position: relative;
  aspect-ratio: 1;
  border-radius: 50%;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: radial-gradient(circle at 30% 28%, rgba(255, 255, 255, 0.16), rgba(9, 14, 24, 0.96) 68%);
  box-shadow: inset 0 -10px 18px rgba(0, 0, 0, 0.35);
}

.cell[data-state='Red'] {
  background: radial-gradient(circle at 30% 28%, rgba(255, 255, 255, 0.3), rgba(230, 54, 54, 0.98) 70%);
}

.cell[data-state='Yellow'] {
  background: radial-gradient(circle at 30% 28%, rgba(255, 255, 255, 0.42), rgba(246, 196, 67, 0.98) 70%);
}

.cell[data-winning='true'] {
  box-shadow: 0 0 0 3px rgba(110, 231, 255, 0.9), inset 0 -10px 18px rgba(0, 0, 0, 0.35);
}

.action-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 18px;
}

.history-panel {
  position: sticky;
  top: 16px;
}

.history-list {
  list-style: none;
  margin: 16px 0 0;
  padding: 0;
  display: grid;
  gap: 10px;
  max-height: 540px;
  overflow: auto;
}

.history-list li {
  padding: 12px 14px;
  border-radius: 16px;
  background: rgba(6, 10, 22, 0.56);
  border: 1px solid rgba(148, 163, 184, 0.16);
  line-height: 1.35;
}

.availability-text {
  text-align: right;
}

@media (max-width: 920px) {
  .game-grid {
    grid-template-columns: 1fr;
  }

  .history-panel {
    position: static;
  }
}

@media (max-width: 560px) {
  body {
    padding: 12px;
  }

  .topbar {
    flex-direction: column;
  }

  .auth-panel,
  .board-panel,
  .history-panel {
    padding: 18px;
  }

  .scoreboard {
    grid-template-columns: 1fr;
  }

  .column-controls {
    gap: 6px;
  }

  .column-controls button {
    min-height: 40px;
    padding-inline: 4px;
    font-size: 0.92rem;
  }

  .board-frame {
    padding: 10px;
    border-radius: 22px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

const state = {
  token: localStorage.getItem('droplineToken') || '',
  session: null,
  loading: false,
};

const authScreen = document.getElementById('authScreen');
const gameScreen = document.getElementById('gameScreen');
const loginForm = document.getElementById('loginForm');
const emailInput = document.getElementById('emailInput');
const passwordInput = document.getElementById('passwordInput');
const authFeedback = document.getElementById('authFeedback');
const accountBadge = document.getElementById('accountBadge');
const statusText = document.getElementById('statusText');
const turnHint = document.getElementById('turnHint');
const redWinsValue = document.getElementById('redWinsValue');
const yellowWinsValue = document.getElementById('yellowWinsValue');
const drawsValue = document.getElementById('drawsValue');
const columnControls = document.getElementById('columnControls');
const board = document.getElementById('board');
const gameFeedback = document.getElementById('gameFeedback');
const newGameButton = document.getElementById('newGameButton');
const undoButton = document.getElementById('undoButton');
const redoButton = document.getElementById('redoButton');
const signOutButton = document.getElementById('signOutButton');
const historyList = document.getElementById('historyList');
const availabilityText = document.getElementById('availabilityText');

let columnButtons = [];
let boardCells = [];

function setSignedOut() {
  state.session = null;
  authScreen.classList.remove('hidden');
  gameScreen.classList.add('hidden');
  accountBadge.hidden = true;
  setFeedback(authFeedback, '');
  setFeedback(gameFeedback, '');
  loginForm.reset();
  passwordInput.focus();
}

function setSignedIn(session) {
  state.session = session;
  authScreen.classList.add('hidden');
  gameScreen.classList.remove('hidden');
  accountBadge.hidden = false;
  accountBadge.textContent = `Signed in as ${session.account.name} · ${session.account.email}`;
  renderSession(session);
}

function setFeedback(element, message) {
  element.textContent = message || '';
}

function ensureBoardCells() {
  if (boardCells.length) {
    return;
  }
  board.innerHTML = '';
  for (let index = 0; index < 42; index += 1) {
    const cell = document.createElement('div');
    cell.className = 'cell';
    cell.setAttribute('role', 'gridcell');
    cell.setAttribute('aria-label', 'Row 1, Column 1, empty');
    cell.dataset.state = 'empty';
    board.appendChild(cell);
    boardCells.push(cell);
  }
}

function ensureColumnControls() {
  if (columnButtons.length) {
    return;
  }
  columnControls.innerHTML = '';
  for (let column = 1; column <= 7; column += 1) {
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = `Drop in column ${column}`;
    button.dataset.column = String(column);
    button.addEventListener('click', () => dropColumn(column));
    button.addEventListener('keydown', handleColumnKeydown);
    columnControls.appendChild(button);
    columnButtons.push(button);
  }
}

function handleColumnKeydown(event) {
  const index = columnButtons.indexOf(event.currentTarget);
  if (index === -1) {
    return;
  }

  if (event.key === 'ArrowLeft') {
    event.preventDefault();
    const nextIndex = Math.max(0, index - 1);
    columnButtons[nextIndex].focus();
    return;
  }

  if (event.key === 'ArrowRight') {
    event.preventDefault();
    const nextIndex = Math.min(columnButtons.length - 1, index + 1);
    columnButtons[nextIndex].focus();
    return;
  }

  if (event.key === 'Home') {
    event.preventDefault();
    columnButtons[0].focus();
    return;
  }

  if (event.key === 'End') {
    event.preventDefault();
    columnButtons[columnButtons.length - 1].focus();
    return;
  }

  if (event.key === 'Enter' || event.key === ' ') {
    event.preventDefault();
    dropColumn(index + 1);
  }
}

function cellLabel(row, column, cellState, winning) {
  let label = `Row ${row}, Column ${column}, ${cellState}`;
  if (winning) {
    label += ', winning';
  }
  return label;
}

function renderBoard(session) {
  ensureBoardCells();
  const winningSet = new Set(session.winningCells || []);
  for (let index = 0; index < boardCells.length; index += 1) {
    const cell = boardCells[index];
    const row = Math.floor(index / 7) + 1;
    const column = (index % 7) + 1;
    const cellState = session.board[index] || 'empty';
    const winning = winningSet.has(index);
    cell.dataset.state = cellState;
    cell.dataset.winning = winning ? 'true' : 'false';
    cell.setAttribute('aria-label', cellLabel(row, column, cellState, winning));
  }
}

function renderHistory(history) {
  historyList.innerHTML = '';
  if (!history.length) {
    const empty = document.createElement('li');
    empty.textContent = 'No moves yet.';
    historyList.appendChild(empty);
    return;
  }

  for (const move of history) {
    const item = document.createElement('li');
    item.textContent = `${move.moveNumber}. ${move.color} — column ${move.column}, row ${move.row}`;
    historyList.appendChild(item);
  }
}

function renderSession(session) {
  setFeedback(gameFeedback, session.feedback || '');
  statusText.textContent = session.statusText;
  turnHint.textContent = session.status === 'active'
    ? 'Drop a disc into any column.'
    : 'Use New game, Undo, or Redo to continue exploring the saved round.';
  redWinsValue.textContent = String(session.totals.redWins);
  yellowWinsValue.textContent = String(session.totals.yellowWins);
  drawsValue.textContent = String(session.totals.draws);
  renderBoard(session);
  renderHistory(session.history);
  undoButton.disabled = !session.canUndo;
  redoButton.disabled = !session.canRedo;
  newGameButton.disabled = false;
  signOutButton.disabled = false;
  setColumnControlsDisabled(session.status !== 'active');
  availabilityText.textContent = [
    session.canUndo ? 'Undo available' : 'Nothing to undo',
    session.canRedo ? 'Redo available' : 'Nothing to redo',
  ].join(' · ');
}

function setColumnControlsDisabled(disabled) {
  ensureColumnControls();
  for (const button of columnButtons) {
    button.disabled = disabled;
  }
}

async function request(path, options = {}) {
  const headers = new Headers(options.headers || {});
  if (state.token) {
    headers.set('Authorization', `Bearer ${state.token}`);
  }
  if (options.body && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  const response = await fetch(path, {
    ...options,
    headers,
  });

  const text = await response.text();
  const payload = text ? JSON.parse(text) : {};
  if (!response.ok) {
    const message = payload.error || 'Unexpected request failure.';
    const error = new Error(message);
    error.status = response.status;
    throw error;
  }
  return payload;
}

async function bootstrap() {
  ensureBoardCells();
  ensureColumnControls();

  if (!state.token) {
    setSignedOut();
    return;
  }

  try {
    const payload = await request('/api/bootstrap');
    state.token = payload.token || state.token;
    localStorage.setItem('droplineToken', state.token);
    setSignedIn(payload);
  } catch (error) {
    state.token = '';
    localStorage.removeItem('droplineToken');
    setSignedOut();
    setFeedback(authFeedback, 'Your session expired. Please sign in again.');
  }
}

async function submitLogin(event) {
  event.preventDefault();
  setFeedback(authFeedback, '');
  const email = emailInput.value.trim();
  const password = passwordInput.value;
  if (!email || !password) {
    setFeedback(authFeedback, 'Enter both email and password.');
    return;
  }

  loginForm.querySelector('button[type="submit"]').disabled = true;
  try {
    const payload = await request('/api/login', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    });
    state.token = payload.token;
    localStorage.setItem('droplineToken', state.token);
    setSignedIn(payload);
  } catch (error) {
    setFeedback(authFeedback, error.message);
  } finally {
    loginForm.querySelector('button[type="submit"]').disabled = false;
  }
}

async function performAction(path) {
  if (state.loading) {
    return;
  }
  state.loading = true;
  setFeedback(gameFeedback, '');
  try {
    const payload = await request(path, { method: 'POST', body: '{}' });
    setSignedIn(payload);
  } catch (error) {
    setFeedback(gameFeedback, error.message);
  } finally {
    state.loading = false;
  }
}

function dropColumn(column) {
  performAction('/api/move', { column });
}

// Override performAction for payload-specific requests.
const originalPerformAction = performAction;
performAction = async function performActionWithBody(path, body = {}) {
  if (state.loading) {
    return;
  }
  state.loading = true;
  setFeedback(gameFeedback, '');
  try {
    const payload = await request(path, {
      method: 'POST',
      body: JSON.stringify(body),
    });
    setSignedIn(payload);
  } catch (error) {
    setFeedback(gameFeedback, error.message);
  } finally {
    state.loading = false;
  }
};

loginForm.addEventListener('submit', submitLogin);
newGameButton.addEventListener('click', () => performAction('/api/new-game'));
undoButton.addEventListener('click', () => performAction('/api/undo'));
redoButton.addEventListener('click', () => performAction('/api/redo'));
signOutButton.addEventListener('click', async () => {
  if (!state.token) {
    setSignedOut();
    return;
  }
  try {
    await request('/api/logout', { method: 'POST', body: '{}' });
  } catch {
    // Even if logout fails, clear the local token.
  } finally {
    state.token = '':
    localStorage.removeItem('droplineToken');
    setSignedOut();
  }
});

board.addEventListener('pointerdown', () => {
  board.blur?.();
});

ensureBoardCells();
ensureColumnControls();
bootstrap();

