    console.log('move', column, r.statusText, r.totals.redWins, r.history.length);
    token = a1.token;
  }
  const win = await post('/api/move', token, { column: 1 });
  console.log('win', win.statusText, win.totals.redWins, win.winningCells.length, win.history.length);
